Contract SubmitLoanRequestModule::enterLoanInformation(requestid:Integer,name:String,loanamount:Real,loanpurpose:String,income:Real,phonenumber:Integer,postaladdress:String,zipcode:Integer,email:String,workreferences:String,creditreferences:String,checkingaccountnumber:Integer,securitynumber:Integer): Boolean {

            precondition:
          LoanRequest.allInstances()->forAll(lr:LoanRequest|lr.requestid <> requestid)

            postcondition:
          result = true and CurrentLoanRequest.oclIsNew() and LoanRequest.allInstances()->includes(CurrentLoanRequest) and CurrentLoanRequest.requestid = requestid and CurrentLoanRequest.name = name and CurrentLoanRequest.loanamount = loanamount and CurrentLoanRequest.loanpurpose = loanpurpose and CurrentLoanRequest.income = income and CurrentLoanRequest.phonenumber = phonenumber and CurrentLoanRequest.postaladdress = postaladdress and CurrentLoanRequest.zipcode = zipcode and CurrentLoanRequest.email = email and CurrentLoanRequest.workreferences = workreferences and CurrentLoanRequest.creditreferences = creditreferences and CurrentLoanRequest.checkingaccountnumber = checkingaccountnumber and CurrentLoanRequest.securitynumber = securitynumber

        }
